});

test('throws RangeError for Infinity wpm', () => {
  assert.throws(() => readingTimeMinutes('text', Infinity), (err) => {
    assert.ok(err instanceof RangeError);
    assert.ok(err.message.startsWith('readingTimeMinutes:'));
    return true;
  });
});

test('throws RangeError for -Infinity wpm', () => {
  assert.throws(() => readingTimeMinutes('text', -Infinity), (err) => {
    assert.ok(err instanceof RangeError);
    assert.ok(err.message.startsWith('readingTimeMinutes:'));
    return true;
